{
  "lecture": [
    {
      "etiquette": "F36",
      "R1": {
        "valeur": 1,
        "passage": "à calcul égal, au moins 20 % de composantes plantées couvertes en plus après six générations qu'une trajectoire unique à carnet continu"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes, lois fausses et copies promues, lues par l'oracle après la course ; dollars relevés par branche et par génération"
      },
      "R3": {
        "valeur": 0,
        "motif": "La branche poursuivie est sélectionnée sur le nombre de lois retenues par le juge, sans nommer cette objection ni expliquer pourquoi elle ne s'appliquerait pas."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 1,
        "passage": "vider le carnet dans chaque branche ; jouer deux générations dans chacune avec le tiers du budget de proposeurs par branche ; garder la branche qui a retenu le plus de lois"
      },
      "R6": {
        "valeur": 1,
        "passage": "environ 1,5 fois le coût d'une course témoin sur les horizons de branche, soit de l'ordre de 300 USD pour trente mondes et six générations, témoins compris"
      },
      "R7": {
        "valeur": 1,
        "passage": "Le carnet qui repart vide casse l'ancrage sur les premières idées, sans perdre ce que l'archive a acquis"
      },
      "N": {
        "valeur": "C5",
        "passage_fiche": "puis, toutes les deux générations, dédoubler la course en trois branches parallèles : chacune hérite de l'archive, des cartes produites et de l'espace de travail accumulé, mais repart d'un carnet vide. Après un horizon fixe de deux générations, la course continue depuis la branche qui a retenu le plus de lois ; les autres sont abandonnées.",
        "passage_catalogue": "Périodiquement, l'agent est **dédoublé en trajectoires parallèles** qui héritent de l'espace de travail accumulé mais repartent d'un **contexte de conversation neuf** ; après un horizon fixe, on **continue depuis la trajectoire au meilleur score** ; comparé, à calcul égal, à une exécution unique et au meilleur de N."
      }
    },
    {
      "etiquette": "F37",
      "R1": {
        "valeur": 1,
        "passage": "À coût total (appels aux modèles et tirages d'épisodes du monde) strictement égal, l'allocation séquentielle augmente de 30 % le nombre de composantes plantées vraies couvertes par l'oracle"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle du nombre total de composantes plantées vraies couvertes (D2) et de fausses promotions rapportés au coût total consommé (jetons et épisodes tirés)"
      },
      "R3": {
        "valeur": 0,
        "motif": "Les valeurs e et les retenues du juge commandent l'arrêt des courses et la sélection de celles recevant de nouveaux appels de proposeurs, sans justification d'une réouverture de cette interdiction."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 0,
        "motif": "La fiche ne précise ni la valeur finale des groupes éliminés à l'amorçage ni la règle de partage des crédits entre les courses admissibles."
      },
      "R6": {
        "valeur": 1,
        "passage": "L'expérience décisive la moins chère qui la tuerait se fait sur processeur seul (zéro dépense d'appel)"
      },
      "R7": {
        "valeur": 0,
        "motif": "La validité de l'arrêt optionnel n'établit pas que les seuils précoces et l'arrêt après zéro retenue distinguent les courses sans avenir des découvertes conditionnelles encore accessibles."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F38",
      "R1": {
        "valeur": 1,
        "passage": "le nombre de composantes plantées vraies couvertes par l'oracle dans les retenues augmente d'au moins 30 % par rapport à la composition monolithique à une passe"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (nombre de composantes plantées vraies couvertes dans les propositions brutes, les représentants et les retenues, et nombre de lois fausses ou copies promues)"
      },
      "R3": {
        "valeur": 0,
        "motif": "La maximisation numérique de la distance de Jaccard à l'archive réintroduit un critère de nouveauté dans la sélection des cibles imposées aux agents, sans traiter l'objection correspondante."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:composition"
      },
      "R5": {
        "valeur": 0,
        "motif": "L'extraction des tuples d'une loi de l'archive n'est pas définie et aucune règle ne couvre le cas où moins de six tuples subsistent après filtrage."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dizaines de dollars d'appels) : comparer par l'oracle la couverture des 6 cartes issues du couplage Passe 1 + Passe 2 contre les 6 cartes d'un appel monolithique à coût supérieur ou égal."
      },
      "R7": {
        "valeur": 0,
        "motif": "La déduplication syntaxique des tuples et leur éloignement de l'archive n'impliquent pas davantage de composantes vraies couvertes, notamment lorsque de nouvelles lois réutilisent les mêmes traits."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F39",
      "R1": {
        "valeur": 1,
        "passage": "à budget d'épisodes du test de mort égal, au moins 20 % de composantes plantées couvertes en plus par génération que l'ordre d'arrivée actuel"
      },
      "R2": {
        "valeur": 1,
        "passage": "composantes plantées couvertes par génération et lois fausses retenues, lues par l'oracle après la course ; dollars des juges à modèle relevés par les relais"
      },
      "R3": {
        "valeur": 0,
        "motif": "Les scores Elo produits par des juges à modèle déterminent quelles cartes accèdent au test de mort et donc à la sélection, sans justification de cette levée de contrainte."
      },
      "R4": {
        "valeur": 0,
        "motif": "La fiche ne nomme aucune garantie statistique restant démontrable ni le nul contre lequel elle serait assurée."
      },
      "R5": {
        "valeur": 1,
        "passage": "les cotes se mettent à jour avec un facteur K = 32 ; huit tours. Le test de mort prend ensuite les cartes par cote décroissante jusqu'à épuisement de ses épisodes."
      },
      "R6": {
        "valeur": 1,
        "passage": "de l'ordre de 3 USD de juges à modèle par génération, soit environ 120 USD pour quarante mondes, le test de mort et l'ordre tiré au hasard se rejouant sur processeur"
      },
      "R7": {
        "valeur": 0,
        "motif": "Qualifier les cartes préférées des modèles de plus prometteuses ne fournit aucun lien directionnel entre leur cote Elo et la couverture vraie mesurée par l'oracle."
      },
      "N": {
        "valeur": "C1",
        "passage_fiche": "faire précéder le test de mort d'un tournoi à cotes Elo entre cartes, où des juges à modèle comparent les cartes deux à deux, fait-il couvrir davantage de composantes au même budget d'épisodes ? Les mieux classées se départagent en débats à plusieurs tours, les autres en une comparaison ; les paires sont tirées entre cartes proches, et le test de mort suit l'ordre des cotes.",
        "passage_catalogue": "Un agent de classement tient un **tournoi à cotes Elo** (1 200 au départ) entre hypothèses, par **comparaisons appariées** : débats à plusieurs tours pour les mieux classées, une seule comparaison pour les autres ; les paires sont tirées de préférence entre hypothèses semblables (graphe d'un agent de proximité) ; le classement oriente l'évolution des hypothèses."
      }
    }
  ]
}
